#include <stdio.h>

typedef struct {
    int x;
    int y;
} Point;

int distance_squared(Point a, Point b) {
    int dx = a.x - b.x;
    int dy = a.y - b.y;
    return dx * dx + dy * dy;
}

int main() {
    Point start = {1, 2};
    Point end = {4, 6};
    printf("%d\n", distance_squared(start, end));
    return 0;
}
